#include <bits/stdc++.h>
using namespace std;

struct Orientation {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> tr;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                tr.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto& [a, b] : tr) { minx = min(minx, a); miny = min(miny, b); }
            for (auto& [a, b] : tr) { a -= minx; b -= miny; }
            sort(tr.begin(), tr.end());
            if (seen.insert(tr).second) {
                int maxx = 0, maxy = 0;
                for (auto [a, b] : tr) { maxx = max(maxx, a); maxy = max(maxy, b); }
                res.push_back({tr, maxx + 1, maxy + 1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    int totalCells = 0;
    vector<int> ks(n);
    vector<vector<pair<int,int>>> rawCells(n);
    for (int i = 0; i < n; i++) {
        cin >> ks[i];
        rawCells[i].resize(ks[i]);
        for (int j = 0; j < ks[i]; j++) {
            cin >> rawCells[i][j].first >> rawCells[i][j].second;
        }
        totalCells += ks[i];
    }

    vector<vector<Orientation>> allOrients(n);
    for (int i = 0; i < n; i++) {
        allOrients[i] = getOrientations(rawCells[i]);
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        return ks[a] > ks[b];
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    auto startTime = chrono::steady_clock::now();

    auto tryWidth = [&](int W) {
        int maxH = totalCells + 10;
        if ((long long)W * maxH > 20000000LL) maxH = 20000000LL / W;
        if (maxH < 1) return;

        vector<int> colH(W, 0);
        vector<vector<bool>> grid(W, vector<bool>(maxH, false));
        int curMaxH = 0;
        vector<int> px(n), py(n), pr(n), pf(n);

        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];
            int bestScore = INT_MAX;
            int bx=-1, by=-1, bor=-1;

            for (int oi = 0; oi < (int)allOrients[i].size(); oi++) {
                auto& ori = allOrients[i][oi];
                if (ori.w > W) continue;
                for (int x = 0; x <= W - ori.w; x++) {
                    int minY = 0;
                    for (auto [cx, cy] : ori.cells) minY = max(minY, colH[x+cx] - cy);
                    if (minY < 0) minY = 0;
                    for (int y = minY; y + ori.h <= maxH; y++) {
                        bool ok = true;
                        for (auto [cx,cy] : ori.cells) if (grid[x+cx][y+cy]) { ok=false; break; }
                        if (ok) {
                            int mh = max(curMaxH, y + ori.h);
                            long long score = (long long)mh * 100000 + y * 100 + x;
                            if (score < bestScore) { bestScore = score; bx=x; by=y; bor=oi; }
                            break;
                        }
                        if (y > minY + 30) break;
                    }
                }
            }
            if (bx < 0) return;
            auto& ori = allOrients[i][bor];
            px[i]=bx; py[i]=by; pr[i]=ori.r; pf[i]=ori.f;
            for (auto [cx,cy] : ori.cells) {
                grid[bx+cx][by+cy] = true;
                colH[bx+cx] = max(colH[bx+cx], by+cy+1);
                curMaxH = max(curMaxH, by+cy+1);
            }
        }
        int area = W * curMaxH;
        if (area < bestArea) {
            bestArea = area; bestW = W; bestH = curMaxH;
            bestX=px; bestY=py; bestR=pr; bestF=pf;
        }
    };

    int sq = max(1, (int)ceil(sqrt((double)totalCells)));
    for (int w = max(1, sq - 50); w <= sq + 300 && w <= totalCells + 10; w++) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 8000) break;
        tryWidth(w);
    }

    if (bestArea == INT_MAX) {
        tryWidth(totalCells + 10);
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
    }
    return 0;
}
